number-of-1-bits:
class Solution:
    def hammingWeight(self, n: int) -> int:
        cnt = 0
        while n:
            n &= n - 1
            cnt += 1
        return cnt

number-of-common-factors:
class Solution:
    def commonFactors(self, a: int, b: int) -> int:
        g = a
        x = b
        while x:
            g, x = x, g % x
        cnt = 0
        d = 1
        while d * d <= g:
            if g % d == 0:
                cnt += 1 if d * d == g else 2
            d += 1
        return cnt

number-of-days-between-two-dates:
class Solution:
    def daysBetweenDates(self, date1: str, date2: str) -> int:
        import datetime
        a = [int(x) for x in date1.split('-')]
        b = [int(x) for x in date2.split('-')]
        return abs((datetime.date(b[0], b[1], b[2]) - datetime.date(a[0], a[1], a[2])).days)

number-of-distinct-averages:
class Solution:
    def distinctAverages(self, nums: list[int]) -> int:
        a = sorted(nums)
        seen = set()
        i = 0
        j = len(a) - 1
        while i < j:
            seen.add(a[i] + a[j])
            i += 1
            j -= 1
        return len(seen)

number-of-good-pairs:
class Solution:
    def numIdenticalPairs(self, nums: list[int]) -> int:
        cnt = {}
        total = 0
        for v in nums:
            total += cnt.get(v, 0)
            cnt[v] = cnt.get(v, 0) + 1
        return total

number-of-lines-to-write-string:
class Solution:
    def numberOfLines(self, widths: list[int], s: str) -> list[int]:
        lines = 1
        cur = 0
        for c in s:
            w = widths[ord(c) - 97]
            if cur + w > 100:
                lines += 1
                cur = w
            else:
                cur += w
        return [lines, cur]
